import math


TX_MIN, TX_MAX = 28.0, 32.0
TY_MIN, TY_MAX = 2.0, 5.0
TARGET_X, TARGET_Y = 30.0, 3.5

G1_X, G1_Y = 13.0, 2.0
G2_X, G2_Y = 23.0, 2.4

DRAIN_LO, DRAIN_HI = 14.5, 17.0
SLIP_LO, SLIP_HI = 17.5, 20.0
WIND_LO, WIND_HI = 20.5, 28.0
WIND_AMP = 20.0
WIND_OMEGA = 0.055

MAX_THRUST = 60.0
LOW_THRUST = 45.0
HEAT_SAFE_FRAC = 0.85  # Reduced to be more aggressive with heat management


def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)


def build_agent(sandbox):
    return None


def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return
    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat
    step_idx = sandbox.get_step_count() if hasattr(sandbox, "get_step_count") else step_count

    # Basic target check
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 75.0)
        return

    # Avoid getting stuck in low-velocity regions
    if x > 31.0 and y < 2.0:
        sandbox.apply_thrust(-150.0, 200.0)
        return

    # Calculate thrust magnitude with aggressive heat management
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.2)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.3)

    # Adjust for heat-sensitive regions
    if overheat_limit <= 40000.0:
        heat_frac = heat / overheat_limit
        if heat_frac > 0.3:
            thrust_mag = 40.0
        else:
            thrust_mag = 60.0

    # Reduce thrust in early stages
    if x < 10.0:
        thrust_mag = min(100.0, thrust_mag)

    # Increase thrust in drain regions (but cautiously)
    if DRAIN_LO <= x <= DRAIN_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.3)

    # Avoid excessive thrust in slip regions
    if SLIP_LO <= x <= SLIP_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 0.8)

    # Avoid excessive thrust in wind regions
    if WIND_LO <= x <= WIND_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 0.9)

    # If thrust is too low, apply minimum thrust
    if thrust_mag < 75.0 and overheat_limit > 40000.0:
        sandbox.apply_thrust(0.0, 75.0)
        return

    # Calculate waypoint
    wx, wy = _waypoint(x, y)
    if x > 24.0:
        wy = 4.0
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 75.0)
        return

    ux = dx / dist
    uy = dy / dist
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Reduce vertical thrust in low-altitude regions
    if y < 1.4:
        fy += 30.0  # Reduced from 50.0 to 30.0

    # Add minimal force for gate passage
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(20.0, (1.2 - y) * 30.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 80.0  # Reduced from 110.0

    # Add vertical boost for higher altitudes
    if x > 25.0 and y < 3.0:
        fy += 100.0  # Reduced from 120.0

    # Adjust for wind forces
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy -= wind_fy

    # Cap thrust to prevent overheating
    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 2.0
    if y < 1.4:
        cap = max(cap, 150.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        cap = max(cap, 200.0)

    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    sandbox.apply_thrust(fx, fy)
